import type { NetworkId } from "@mavna/core";

/**
 * Where CCTP lives on every EVM chain that routes into Stellar.
 *
 * Generated by `node scripts/verify-cctp-chains.mjs` on 11 August 2026, and not one
 * address here was typed in by a human. For each chain the script confirmed there
 * is code at the TokenMessengerV2 address, asked that contract for its local
 * minter, asked the minter which token is local USDC, and then asked the token
 * whether it agrees it is USDC with six decimals. A chain that could not answer
 * all four is absent rather than guessed at.
 *
 * That matters because a previous draft of this project carried a bridge's
 * contract addresses that had been dead for five months. Deriving from the chain
 * cannot go stale in the same silent way, and re-running the script is the check.
 *
 * Names and explorers come from the community chain registry for the same reason.
 * A wrong explorer link is not dangerous the way a wrong contract address is, but
 * it is still a link someone clicks expecting to find their transaction.
 *
 * Absent, with the reason for each:
 *   - testnet/morph-holesky: fetch failed
 *   - testnet/pharos-testnet: non-JSON reply (HTTP 403)
 *   - mainnet/arc: ARC_MAINNET is not enabled for this app. Visit this page to enable the network: https:
 *   - mainnet/edge: no TokenMessengerV2 code at the deterministic address
 *
 * The first three are endpoints unreachable from here, not chains known to lack a
 * deployment; re-running the script from somewhere with access is all that is
 * needed. EDGE mainnet is different: the chain answered and there is no
 * TokenMessengerV2 at the address, while its testnet verified, so the mainnet
 * deployment appears not to have happened yet.
 */

export interface EvmDeployment {
  /** Circle's own identifier for the chain. NOT a chain id, and never treat it as one. */
  readonly domain: number;
  /** The EVM chain id, which is what a wallet needs in order to switch networks. */
  readonly evmChainId: number;
  readonly name: string;
  readonly tokenMessengerV2: string;
  readonly usdc: string;
  /** Undefined where no explorer is published. Better than a link that 404s. */
  readonly explorer: string | undefined;
}

